/**
 * Test flow for log action
 * Demonstrates logging a message
 */

import { action, Flow, wfa, trigger } from '@servicenow/sdk/automation'

export const testLog = Flow(
    {
        $id: Now.ID['test_log_flow'],
        name: 'Test Log',
        description: 'Tests the log core action',
    },
    wfa.trigger(
        trigger.record.created,
        { $id: Now.ID['test_log_trigger'] },
        {
            table: 'incident',
            condition: 'active=true',
            run_flow_in: 'background',
        }
    ),
    (_params) => {
        wfa.action(
            action.core.log,
            { $id: Now.ID['test_log_action'] },
            {
                log_level: 'info',
                log_message: `Test log message for incident ${wfa.dataPill(_params.trigger.current.number, 'integer')}`,
            }
        )

        wfa.action(
            action.core.log,
            { $id: Now.ID['test_log_log'] },
            {
                log_level: 'info',
                log_message: `log outputs: (no outputs)`,
            }
        )
    }
)
